    queue.add(start);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Dequeue the current n-tersection
        int[] curr = queue.poll();

        // Check if the current n-tersection is the ending n-tersection
        if (curr[0] == end[0] && curr[1] == end[1]) {
            // If it is, return "can be travelled"
            return "can be travelled";
        }

        // Loop through all the paths from the current n-tersection
        for (int[] neighbor : paths[curr[0]][curr[1]]) {
            // Get the coordinates of the neighboring n-tersection
            int x = neighbor[0];
            int y = neighbor[1];

            // Check if the neighboring n-tersection is valid and not visited
            if (x >= 0 && x < n && y >= 0 && y < n && !visited[x][y]) {
