/**
 * Reverses the characters of each word in the given string while maintaining the original word order.
 *
 * @param s      The input string containing words separated by spaces.
 * @return The string with characters of each word reversed.
 */
public static String reverseWords(String s) {
    // Edge case: If the input string is null or empty, return an empty string
    if (s == null || s.isEmpty()) {
        return "";
    }

    // Split the input string into an array of words
    String[] words = s.split(" ");

    // Create a new string builder to store the output
    StringBuilder output = new StringBuilder();

    // Iterate over each word in the input string
    for (String word : words) {
        // Reverse the current word and append it to the output string builder
        output.append(new StringBuilder(word).reverse().toString());
    }

    // Return the reversed string
    return output.toString();
}
